/// <summary>
/// MPJ_26302_NewCustomerNumberGeneration
/// Extension of LogisticsAddressStateEntity
/// </summary>
[ExtensionOf(tableStr(LogisticsAddressStateEntity))]
final class METLogisticsAddressStateEntity_Extension
{
}

Method.Source:
    /// <summary>
    /// Validating the State Prefix
    /// </summary>
    /// <returns>boolean value</returns>
    public boolean validateWrite()
    {
        boolean     ret;

        ret = next validateWrite();

        // Validate State prefix
        if ((strlen(int2Str(this.METStatePrefix))) != strlen(strkeep(int2Str(this.METStatePrefix), METConstants::statePrefixInt)))
        {
            ret = checkFailed("@MET:METStatePrefixEntityValidation");
        }

        //MPJ_30133_Country region Liquor License DCP 24/08/2022
        //If 'ValidateTobaccoLicence' is YES and ResonCode is blank then error
        if(this.METValidateTobaccoLicence && !this.METTobaccoReasonCode)
        {
            ret = checkFailed("@MET:ReasonCodeMissing");
        }

        return ret;
    }
